/**
 * NEXUS EYE v0.4.9 — /api/cam  (honesty: bounded retry, named camera-state errors, 4 dead TxDOT cams removed)
 * NOT an open proxy. One allowlisted upstream only:
 *   TxDOT ITS public camera snapshots (its.txdot.gov — the same endpoint TxDOT's own public ITS map uses).
 * TxDOT returns base64 JPEG inside JSON with no CORS headers, so the browser can't use it directly.
 * This function: validates params against a fixed district list + strict id pattern + an exact
 * allowlist of the 3,283 TxDOT camera ids shipped in the v0.3.8 pack (anything else → 404, no upstream call),
 * fetches ONE camera snapshot, decodes it to image/jpeg, caches ~60s per camera.
 * Query: /api/cam?s=txdot&d=<DISTRICT>&id=<icd_Id>
 * Abuse/load guards (glassfix): platform rateLimit config + in-memory per-IP limiter, 60s negative cache,
 * 2 MB upstream response cap, kill switch (env CAM_DISABLED=1 → 503), identifying UA with contact URL (+ CAM_CONTACT_EMAIL when set).
 * Origin check is SOFT (a browser hint only — curl can omit it; the allowlist + limits are the real guard).
 * No keys. No arbitrary URLs.
 */
export const config = {
  path: "/api/cam",
  rateLimit: { windowLimit: 120, windowSize: 60, aggregateBy: ["ip", "domain"] },
};

const UPSTREAM = "https://its.txdot.gov/its/DistrictIts/GetCctvSnapshotByIcdId";
const UPSTREAM_HOST = "its.txdot.gov";
/* R3 N-a: contact email goes in the UA only when the operator sets CAM_CONTACT_EMAIL (none is on file — none invented);
   otherwise the site URL is the contact. */
const UA_BASE = "NEXUS-EYE/0.4.9 (+https://nexus-eye-doublea.netlify.app/";
function uaString() {
  const e = String(process.env.CAM_CONTACT_EMAIL || "").trim();
  return UA_BASE + (/^[^\s@<>()";,]+@[^\s@<>()";,]+\.[a-z]{2,}$/i.test(e) ? "; " + e : "") + ")";
}
